export type ConfigValue_Serialize = ({ Text: string }) & { Bool?: never; Choice?: never; Number?: never; Secret?: never } | 
/**  A credential. Rendered as status + source, never as the value. */
({ Secret: SecretValue_Serialize }) & { Bool?: never; Choice?: never; Number?: never; Text?: never } | ({ Bool: boolean }) & { Choice?: never; Number?: never; Secret?: never; Text?: never } | ({ Choice: [string[], number] }) & { Bool?: never; Number?: never; Secret?: never; Text?: never } | ({ Number: number }) & { Bool?: never; Choice?: never; Secret?: never; Text?: never };

