/**  Health of the preferred provider transport. */
export type TransportHealth = 
/**  Preferred transport is responsive. */
"HEALTHY" | 
/**  Preferred transport has partial capability. */
"DEGRADED" | 
/**  Preferred transport is unavailable. */
"UNAVAILABLE" | 
/**  Transport state is not known. */
"UNKNOWN";

/**
 *  TUI cadences and query bounds.
 * 
 *  Separate from `[ui_preferences]` on purpose: that section holds what the
 *  interface LOOKS like (theme, which columns show, sidebar widths) and is
 *  written by the TUI itself. These are performance tunables (how often the
 *  loop wakes, how many rows a query returns) that a user changes for a slow
 *  terminal or a very large fleet and that nothing writes back.
 * 
 *  Example `config.toml`:
 *  ```toml
 *  [ui]
 *  tick_rate_ms = 16      # 60fps event polling
 *  inbox_list_limit = 500
 *  ```
 */
export type UiConfig = {
	/**
	 *  Event-poll cadence in ms: how often the loop wakes to check for a
	 *  keystroke. Drives perceived input latency. ~30fps by default; lower
	 *  costs CPU, higher makes typing feel laggy.
	 */
	tick_rate_ms?: number,
	/**
	 *  App-tick cadence in ms for the heavy periodic work (mascot animation,
	 *  tmux preview capture, OAuth refresh checks). Deliberately much coarser
	 *  than `tick_rate_ms`; running it per poll starves the event loop.
	 */
	app_tick_ms?: number,
	/**
	 *  How many recent hook events the attention-marker query reads per
	 *  refresh. Bounds query cost on a large notifications DB.
	 */
	session_query_limit?: number,
	/**
	 *  Rolling window (hours) an event can still mark a session from. Older
	 *  events never raise a `[?]`/`[!]` marker.
	 */
	session_lookback_hours?: number,
	/**
	 *  Rolling window (hours) a failure keeps lighting an `ERR` chip on a
	 *  session row.
	 * 
	 *  `ERR` had no clock at all: `SessionStatus::Error` never clears by
	 *  itself, so one failure lit a chip for as long as the session existed and
	 *  a whole screen of rows eventually read as broken. Past this window the
	 *  chip retires; the `err` tab still shows the failure, so retiring it
	 *  hides the alarm, never the reason.
	 */
	attention_err_window_hours?: number,
	/**
	 *  Rows the Inbox screen lists. Kept small because the query runs every
	 *  render.
	 */
	inbox_list_limit?: number,
	/**
	 *  Window (ms) in which two clicks count as a double-click on the sidebar
	 *  edge. Raise it if your hands or your terminal are slow.
	 */
	double_click_ms?: number,
	/**
	 *  Seconds an ERROR notice stays on screen before it retires itself.
	 * 
	 *  Five seconds was not long enough to read a failure, let alone act on
	 *  one, so the message had to stay terse to be legible at all — the
	 *  surface was setting the wording. A minute is long enough to read, and
	 *  `Ctrl+X` retires it sooner for anyone who has. Nothing is lost either
	 *  way: every notice is written to the JSONL app log as it is raised, so
	 *  the Log History screen still has it afterwards.
	 */
	notice_error_secs?: number,
	/**
	 *  Seconds a WARNING notice stays on screen.
	 * 
	 *  Shorter than an error because a warning reports a degraded outcome
	 *  rather than a failed one, longer than an info because the operator did
	 *  not ask for it and may not be looking.
	 */
	notice_warning_secs?: number,
	/**
	 *  Seconds an INFO notice stays on screen.
	 * 
	 *  Not all info is a receipt for something the operator just did — a
	 *  degraded Codex launch announces itself this way — so three seconds was
	 *  too short to finish a sentence in.
	 */
	notice_info_secs?: number,
};

export type UiPreferences = UiPreferences_Serialize;

export type UiPreferences_Serialize = {
	/**  Color theme */
	theme: string,
	/**  Whether to show container status in UI */
	show_container_status: boolean,
	/**  Whether to show git status in UI */
	show_git_status: boolean,
	/**
	 *  Whether to show the Sessions-screen bottom keymap legend ("Session
	 *  actions" / "Panels & views"). When false it collapses to a single hint
	 *  row, reclaiming vertical space for the session list. Toggle with ⇧M.
	 */
	show_session_menu_bar: boolean,
	/**  Session-status filter retained across workspace refreshes and restarts. */
	session_filter: SessionFilter,
	/**
	 *  Preferred editor command (e.g., "code", "cursor", "nvim")
	 *  If None, falls back to: code -> $EDITOR -> error
	 */
	preferred_editor: string | null,
	/**
	 *  Preferred HomeScreen sidebar width as a fraction of the screen's width,
	 *  so the same preference draws proportionally on every surface.
	 */
	home_sidebar_fraction: number | null,
	/**
	 *  Preferred Sessions screen sidebar width as a fraction of its row, so
	 *  the same preference draws proportionally on every surface.
	 */
	sessions_sidebar_fraction: number | null,
	/**  Whether the Sessions screen sidebar starts minimized. */
	sessions_sidebar_collapsed: boolean | null,
	/**
	 *  Preferred SkillManager Sources-panel width as a fraction of the
	 *  screen's width. `None` falls back to the 32-column default. Persisted
	 *  on divider-drag / `[`-`]` resize-finish.
	 */
	skill_manager_sources_fraction: number | null,
	/**
	 *  User's response to the "wire up Claude Code statusline" prompt.
	 *  `Unset` means we'll prompt again (init wizard) and surface the
	 *  CTA in the Budget panel. `Declined` suppresses the top-bar CTA
	 *  (the Budget-panel CTA remains visible for power users).
	 */
	statusline_decision: StatuslineDecision,
	/**
	 *  User's response to the "install ainb's rich tmux conf" prompt.
	 *  Same shape as `statusline_decision`. `Unset` re-prompts on next
	 *  `ainb init` if the on-disk conf is Missing or a known-old ainb
	 *  default; `Declined` suppresses the prompt entirely.
	 */
	tmux_decision: TmuxDecision,
	/**
	 *  Which nodes of the Settings screen's category tree are expanded,
	 *  as `"<category label>|<dotted path>"` ids.
	 * 
	 *  Persisted UI state rather than a preference — it sits here beside the
	 *  sidebar widths for the same reason they do: the screen is unusable if
	 *  every section re-collapses on restart, and there is nowhere else that
	 *  survives a restart. Registered `Hidden` in the config registry.
	 */
	config_tree_expanded: string[],
};

/**
 *  Why a row cannot be answered from here.
 * 
 *  Always carries a REASON. "Not answerable" rendered as a greyed chip with no
 *  explanation is the silent no-op the spec forbids: the operator is looking at
 *  something that needs them and has no way to learn why the surface will not
 *  take their answer.
 */
export type Unanswerable = 
/**
 *  The row came from the daemon, and the daemon has since gone away, so the
 *  `attention/answer` call that would deliver the answer is unavailable.
 */
"DaemonGone" | 
/**
 *  The session has no live pane to type into and no daemon row to answer
 *  through — nothing to deliver an answer over at all.
 */
"NoTransport" | 
/**
 *  The state is informational. `DONE` and `ERR` are not questions; there is
 *  nothing to answer.
 */
"NotAQuestion" | 
/**
 *  The agent is rendering its OWN picker for this question, and only that
 *  picker can accept the answer.
 * 
 *  The question and its options are still shown — they arrived in the hook
 *  payload and are worth reading — but a pick cannot be delivered from
 *  here. Typing an option's label into a pane that is waiting on arrow
 *  keys is not an answer, and a composer that looks like it sends one is
 *  the lying surface this screen exists to remove. So the pane shows what
 *  is being asked and says where to answer it.
 */
"NativePicker";

